confirmEmail.usage:
import { confirmEmail } from '@/auth/api/confirmEmail';

confirmEmail({
  customerEmail: 'abc@example.com',
  customerConfirmationKey: '1234567890',
});

createCustomerAddress.usage:
import { createCustomerAddress } from '@/auth/api/createCustomerAddress';

createCustomerAddress(address: {
  "city": "Phoenix",
  "country_code": "US",
  "default_billing": true,
  "default_shipping": false,
  "firstname": "Bob",
  "lastname": "Loblaw",
  "postcode": "77777",
  "region": {
    "region": "Arizona",
    "region_code": "AZ",
  },
  "street": ["123 Main St"],
  "telephone": "555 555-5555",
});

resetPassword.usage:
import { resetPassword } from '@/auth/api/resetPassword';

resetPassword(
